1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
11	type Project = {
12	  id: number;
13	  name: string;
14	  clientId: number;
15	  clientName: string;
16	  archived: boolean;
17	  status: ProjectStatus;
18	};
19	type Invoice = {
20	  id: number;
21	  projectId: number;
22	  amount: number;
23	  amountDue: number;
24	  status: string;
25	  issuedDate: string;
26	  dueDate: string;
27	  discountPct: number;
28	  taxPct: number;
29	};
30	type Task = { id: number; projectId: number; title: string; done: boolean };
31	type Tag = { id: number; name: string };
32	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
33	
34	type LineItem = {
35	  id: number;
36	  invoiceId: number;
37	  description: string;
38	  qty: number;
39	  unit: string;
40	  unitPrice: number;
41	};
42	
43	type Payment = { id: number; invoiceId: number; amount: number; date: string };
44	
45	function money(amount: number): string {
46	  return `$${Number(amount).toLocaleString('en-US', {
47	    minimumFractionDigits: 2,
48	    maximumFractionDigits: 2,
49	  })}`;
50	}
51	
52	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
53	// readable at a glance.
54	function moneyGrouped(amount: number): string {
55	  return `$${Number(amount).toLocaleString('en-US', {
56	    minimumFractionDigits: 2,
57	    maximumFractionDigits: 2,
58	  })}`;
59	}
60	
61	type ProjectBudget = { budget: number | null; invoiced: number; remaining: number | null };
62	
63	// One charge line while it is being edited on screen: the fields are held as raw strings so the
64	// inputs stay controlled and the total can recompute live as they change.
65	type EditItem = { id: number; description: string; qty: string; unit: string; unitPrice: string };
66	
67	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
68	// many, price each), the total worked out for you, and a form to add another line. Each line can be
69	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
70	// own line-item state, scoped to the one invoice it is showing.
71	function InvoiceDetail({
72	  invoiceId,
73	  onChange,
74	  onClose,
75	}: {
76	  invoiceId: number;
77	  onChange: () => void;
78	  onClose: () => void;
79	}) {
80	  const [items, setItems] = useState<EditItem[]>([]);
81	  const [description, setDescription] = useState('');
82	  const [qty, setQty] = useState('');
83	  const [unit, setUnit] = useState('');
84	  const [unitPrice, setUnitPrice] = useState('');
85	  const [payments, setPayments] = useState<Payment[]>([]);
86	  const [paymentAmount, setPaymentAmount] = useState('');
87	  const [paymentDate, setPaymentDate] = useState('');
88	  const [status, setStatus] = useState('');
89	  // The percentage discount taken off this invoice's subtotal (0 unless one is set).
90	  const [discountPct, setDiscountPct] = useState(0);
91	  // The percentage sales tax added on top after the discount (0 unless one is set).
92	  const [taxPct, setTaxPct] = useState(0);
93	
94	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
95	  // a payment is added rather than flipping it by hand. The discount and tax percentages come back
96	  // on the same read.
97	  async function loadStatus() {
98	    const res = await fetch(`/api/invoices/${invoiceId}`);
99	    const inv: Invoice = await res.json();
100	    setStatus(inv.status);
101	    setDiscountPct(Number(inv.discountPct) || 0);
102	    setTaxPct(Number(inv.taxPct) || 0);
103	  }
104	
105	  async function load() {
106	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
107	    const rows: LineItem[] = await res.json();
108	    setItems(
109	      rows.map((li) => ({
110	        id: li.id,
111	        description: li.description,
112	        qty: String(li.qty),
113	        unit: li.unit,
114	        unitPrice: String(li.unitPrice),
115	      })),
116	    );
117	  }
118	
119	  async function loadPayments() {
120	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
121	    setPayments(await res.json());
122	  }
123	
124	  async function submitPayment(e: React.FormEvent) {
125	    e.preventDefault();
126	    const value = Number(paymentAmount);
127	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
128	      return;
129	    }
130	    if (paymentDate.trim() === '') {
131	      return;
132	    }
133	    await fetch(`/api/invoices/${invoiceId}/payments`, {
134	      method: 'POST',
135	      headers: { 'Content-Type': 'application/json' },
136	      body: JSON.stringify({ amount: value, date: paymentDate }),
137	    });
138	    setPaymentAmount('');
139	    setPaymentDate('');
140	    await loadPayments();
141	    await loadStatus();
142	    onChange();
143	  }
144	
145	  useEffect(() => {
146	    void load();
147	    void loadPayments();
148	    void loadStatus();
149	  }, [invoiceId]);
150	
151	  function editField(
152	    id: number,
153	    field: 'description' | 'qty' | 'unit' | 'unitPrice',
154	    value: string,
155	  ) {
156	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
157	  }
158	
159	  function amountOf(li: EditItem): number {
160	    const line = Number(li.qty) * Number(li.unitPrice);
161	    return Number.isFinite(line) ? line : 0;
162	  }
163	
164	  async function save(li: EditItem) {
165	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
166	      return;
167	    }
168	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
169	      method: 'POST',
170	      headers: { 'Content-Type': 'application/json' },
171	      body: JSON.stringify({
172	        description: li.description,
173	        qty: Number(li.qty),
174	        unit: li.unit,
175	        unitPrice: Number(li.unitPrice),
176	      }),
177	    });
178	    await load();
179	    onChange();
180	  }
181	
182	  async function remove(id: number) {
183	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
184	    await load();
185	    onChange();
186	  }
187	
188	  async function submit(e: React.FormEvent) {
189	    e.preventDefault();
190	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
191	      return;
192	    }
193	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
194	      method: 'POST',
195	      headers: { 'Content-Type': 'application/json' },
196	      body: JSON.stringify({
197	        description,
198	        qty: Number(qty),
199	        unit,
200	        unitPrice: Number(unitPrice),
201	      }),
202	    });
203	    setDescription('');
204	    setQty('');
205	    setUnit('');
206	    setUnitPrice('');
207	    await load();
208	    onChange();
209	  }
210	
211	  // The subtotal is the sum of the line items; the discount is that percentage taken off it. Sales
212	  // tax is then added on top of the discounted base (worked out after the discount), and the final
213	  // total is the subtotal less the discount plus that tax.
214	  const subtotal = items.reduce((sum, li) => sum + amountOf(li), 0);
215	  const discount = (subtotal * discountPct) / 100;
216	  const tax = ((subtotal - discount) * taxPct) / 100;
217	  const total = subtotal - discount + tax;
218	
219	  return (
220	    <section data-testid="invoice-detail">
221	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
222	        Back to invoices
223	      </button>
224	
225	      <p data-testid="invoice-status">{status}</p>
226	
227	      <table data-testid="invoice-lineitems-table">
228	        <tbody>
229	          {items.map((li) => (
230	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
231	              <td>
232	                <input
233	                  data-testid="lineitem-description"
234	                  value={li.description}
235	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
236	                />
237	              </td>
238	              <td data-testid="lineitem-qty">{li.qty}</td>
239	              <td data-testid="lineitem-unit">{li.unit}</td>
240	              <td>
241	                <input
242	                  data-testid="lineitem-unitprice"
243	                  value={li.unitPrice}
244	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
245	                />
246	              </td>
247	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
248	              <td>
249	                <button
250	                  data-testid={`lineitem-save-${li.id}`}
251	                  type="button"
252	                  onClick={() => save(li)}
253	                >
254	                  Save
255	                </button>
256	                <button
257	                  data-testid={`lineitem-remove-${li.id}`}
258	                  type="button"
259	                  onClick={() => remove(li.id)}
260	                >
261	                  Remove
262	                </button>
263	              </td>
264	            </tr>
265	          ))}
266	        </tbody>
267	      </table>
268	
269	      <p data-testid="invoice-subtotal">{money(subtotal)}</p>
270	      <p data-testid="invoice-discount">{money(discount)}</p>
271	      <p data-testid="invoice-tax">{money(tax)}</p>
272	      <p data-testid="invoice-amount">{money(total)}</p>
273	
274	      <form data-testid="lineitem-form" onSubmit={submit}>
275	        <input
276	          data-testid="lineitem-form-description"
277	          placeholder="Description"
278	          value={description}
279	          onChange={(e) => setDescription(e.target.value)}
280	        />
281	        <input
282	          data-testid="lineitem-form-qty"
283	          placeholder="How many"
284	          value={qty}
285	          onChange={(e) => setQty(e.target.value)}
286	        />
287	        <input
288	          data-testid="lineitem-form-unit"
289	          placeholder="Unit"
290	          value={unit}
291	          onChange={(e) => setUnit(e.target.value)}
292	        />
293	        <input
294	          data-testid="lineitem-form-unitprice"
295	          placeholder="Price each"
296	          value={unitPrice}
297	          onChange={(e) => setUnitPrice(e.target.value)}
298	        />
299	        <button data-testid="lineitem-form-submit" type="submit">
300	          Add line item
301	        </button>
302	      </form>
303	
304	      <table data-testid="invoice-payments-table">
305	        <tbody>
306	          {payments.map((p) => (
307	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
308	              <td data-testid="payment-amount">{money(p.amount)}</td>
309	              <td data-testid="payment-date">{p.date}</td>
310	            </tr>
311	          ))}
312	        </tbody>
313	      </table>
314	
315	      <form data-testid="payment-form" onSubmit={submitPayment}>
316	        <input
317	          data-testid="payment-form-amount"
318	          placeholder="Amount paid"
319	          value={paymentAmount}
320	          onChange={(e) => setPaymentAmount(e.target.value)}
321	        />
322	        <input
323	          data-testid="payment-form-date"
324	          type="date"
325	          value={paymentDate}
326	          onChange={(e) => setPaymentDate(e.target.value)}
327	        />
328	        <button data-testid="payment-form-submit" type="submit">
329	          Record payment
330	        </button>
331	      </form>
332	    </section>
333	  );
334	}
335	
336	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
337	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
338	// gives one obvious place to add a new lifecycle action.
339	function InvoiceActions({
340	  invoice,
341	  onOpen,
342	  onSend,
343	  onPay,
344	  onCancel,
345	}: {
346	  invoice: Invoice;
347	  onOpen: () => void;
348	  onSend: () => void;
349	  onPay: () => void;
350	  onCancel: () => void;
351	}) {
352	  return (
353	    <>
354	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
355	        Open
356	      </button>
357	      {invoice.status === 'DRAFT' && (
358	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
359	          Send
360	        </button>
361	      )}
362	      {invoice.status === 'SENT' && (
363	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
364	          Mark paid
365	        </button>
366	      )}
367	      {invoice.status === 'SENT' && (
368	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
369	          Cancel
370	        </button>
371	      )}
372	    </>
373	  );
374	}
375	
376	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
377	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
378	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
379	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
380	function ProjectInvoices({
381	  projectId,
382	  onInvoicesChanged,
383	}: {
384	  projectId: number;
385	  onInvoicesChanged: () => void;
386	}) {
387	  const [invoices, setInvoices] = useState<Invoice[]>([]);
388	  const [amount, setAmount] = useState('');
389	  const [amountError, setAmountError] = useState('');
390	  const [sortByDue, setSortByDue] = useState(false);
391	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
392	
393	  async function load() {
394	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
395	    setInvoices(await res.json());
396	    onInvoicesChanged();
397	  }
398	
399	  useEffect(() => {
400	    void load();
401	  }, [projectId]);
402	
403	  async function submit(e: React.FormEvent) {
404	    e.preventDefault();
405	    const value = Number(amount);
406	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
407	      setAmountError('Amount must be more than zero');
408	      return;
409	    }
410	    setAmountError('');
411	    await fetch('/api/invoices', {
412	      method: 'POST',
413	      headers: { 'Content-Type': 'application/json' },
414	      body: JSON.stringify({ projectId, amount: value }),
415	    });
416	    setAmount('');
417	    await load();
418	  }
419	
420	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
421	  // routing them through one place means a new action is one more call site, not new plumbing.
422	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
423	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
424	    await load();
425	  }
426	
427	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
428	  const shownInvoices = sortByDue
429	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
430	    : invoices;
431	
432	  return (
433	    <>
434	      <form data-testid="invoice-form" onSubmit={submit}>
435	        <input
436	          data-testid="invoice-form-amount"
437	          placeholder="Amount"
438	          value={amount}
439	          onChange={(e) => setAmount(e.target.value)}
440	        />
441	        <button data-testid="invoice-form-submit" type="submit">
442	          Add invoice
443	        </button>
444	        {amountError && (
445	          <p data-testid="invoice-form-amount-error" role="alert">
446	            {amountError}
447	          </p>
448	        )}
449	      </form>
450	
451	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
452	        Sort by due date
453	      </button>
454	
455	      {openInvoiceId === null ? (
456	        <>
457	          <table data-testid="project-invoices-table">
458	            <tbody>
459	              {shownInvoices.map((inv) => (
460	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
461	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
462	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
463	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
464	                  <td data-testid="invoice-due">{inv.dueDate}</td>
465	                  <td data-testid="invoice-status">{inv.status}</td>
466	                  <td>
467	                    <InvoiceActions
468	                      invoice={inv}
469	                      onOpen={() => setOpenInvoiceId(inv.id)}
470	                      onSend={() => transition(inv.id, 'send')}
471	                      onPay={() => transition(inv.id, 'pay')}
472	                      onCancel={() => transition(inv.id, 'cancel')}
473	                    />
474	                  </td>
475	                </tr>
476	              ))}
477	            </tbody>
478	          </table>
479	
480	          <p data-testid="project-invoices-total">{money(total)}</p>
481	        </>
482	      ) : (
483	        <InvoiceDetail
484	          invoiceId={openInvoiceId}
485	          onChange={load}
486	          onClose={() => setOpenInvoiceId(null)}
487	        />
488	      )}
